/*
 * A051264  Numbers that are 1-persistent but not 2-persistent.
 * https://oeis.org/A051264
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   numbers that are 1‑persistent but not 2‑persistent. Generated by
 *            enumerating all 10‑digit pandigital numbers in ascending order;
 *            a number is kept if 2×n is not pandigital
 * Range:     u8 none, u16 none, u32 n <= 1000, u64 n <= 1000, u128 n <= 1000,
 *            big any n
 * Helpers:   is_pandigital10, next_permutation
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_pandigital10.h"
#include "../utils/next_permutation.h"

/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/* Data structures for memoised storage of the sequence terms */
static seq_t *terms = NULL;
static size_t terms_count = 0;
static size_t terms_capacity = 0;

/* Append a new term to the dynamic array, resizing if necessary */
static void add_term(seq_t v)
{
    if (terms_count == terms_capacity) {
        size_t new_cap = terms_capacity ? terms_capacity << 1U : 1024;
        seq_t *tmp = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        terms = tmp;
        terms_capacity = new_cap;
    }
    terms[terms_count++] = v;
}

/* ------------------------------------------------------------------ */
/* Generate all terms of A051264 and store them in ascending order. */
static void generate_terms(void)
{
    unsigned digits[10];
    for (unsigned d = 0; d < 10; ++d) digits[d] = d;

    do {
        if (digits[0] == 0)                /* skip numbers with leading 0 */
            continue;

        /* convert digit array to a 64‑bit integer */
        uint64_t n = 0;
        for (int i = 0; i < 10; ++i)
            n = n * 10ULL + (uint64_t)digits[i];

        /* test the 2‑persistent property */
        uint64_t double_n = n * 2ULL;
        if (!is_pandigital10(double_n))   /* not 2‑persistent */
            add_term((seq_t)n);
    } while (next_permutation(digits, 10));
}

/* ------------------------------------------------------------------ */
/* Public entry point for the sequence.  Handles any call order of n. */
seq_t a(idx_t n)
{
    static bool initialized = false;
    if (!initialized) {
        generate_terms();
        initialized = true;
    }

    /* The build guarantees n ≥ 1; values beyond the computed range
       are undefined, but we guard against out‑of‑range access. */
    if (n == (idx_t)0 || (size_t)n > terms_count)
        return (seq_t)0;                 /* undefined behaviour */

    return terms[(size_t)n - 1];
}
